<?php declare(strict_types=1);require_once 'config/auth.php';header('Content-Type: application/json; charset=utf-8');if(!is_logged_in()){http_response_code(401);echo json_encode(['ok'=>false]);exit;}$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT id,order_number,status,total,tracking_number,updated_at FROM orders WHERE id=? AND user_id=?");$stmt->execute([$id,$_SESSION['user_id']]);$o=$stmt->fetch();if(!$o){http_response_code(404);echo json_encode(['ok'=>false]);exit;}$q=$pdo->prepare("SELECT product_name,quantity FROM order_items WHERE order_id=? ORDER BY id");$q->execute([$id]);echo json_encode(['ok'=>true,'id'=>(int)$o['id'],'order_number'=>$o['order_number'],'status'=>$o['status'],'total'=>$o['total'],'tracking_number'=>$o['tracking_number']??'','updated_at'=>$o['updated_at'],'items'=>$q->fetchAll()],JSON_UNESCAPED_UNICODE);